(function(){let e=[],t=[],n=[];self.onmessage=({data:r})=>{if(r.type===`clear`)e=[],t=[],n=[];else{if(r.type===`build`){n=r.nodes.map(e=>e.id),e=n.map(e=>{try{return new URL(e).pathname.toLowerCase()}catch{return e.toLowerCase()}}),t=r.nodes.map(e=>(e.title||``).toLowerCase());let i={type:`ready`,nodeCount:n.length};self.postMessage(i)}if(r.type===`search`){let i=r.query.toLowerCase();if(!i){self.postMessage({type:`results`,matchIds:[]});return}let a=[];for(let r=0;r<n.length&&a.length<200;r++)(e[r].includes(i)||n[r].toLowerCase().includes(i)||t[r].includes(i))&&a.push(n[r]);let o={type:`results`,matchIds:a};self.postMessage(o)}}}})();